import{_ as e,o as a,c as n,a2 as i}from"./chunks/framework.gtmkOXzY.js";const u=JSON.parse('{"title":"Cockpit and flying","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/cockpit.md","filePath":"ms-flightsim/cockpit.md","lastUpdated":null}'),o={name:"ms-flightsim/cockpit.md"};function r(d,t,s,l,h,c){return a(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="cockpit-and-flying" tabindex="-1">Cockpit and flying <a class="header-anchor" href="#cockpit-and-flying" aria-label="Permalink to &quot;Cockpit and flying&quot;">​</a></h1><p>This page explains what the pilot sees in the cockpit, how the autopilot, autoland and auto-hover work, and how wind, malfunctions, fuel and repairs affect a flight.</p><h2 id="the-pfd-cockpit-display" tabindex="-1">The PFD (cockpit display) <a class="header-anchor" href="#the-pfd-cockpit-display" aria-label="Permalink to &quot;The PFD (cockpit display)&quot;">​</a></h2><p>The PFD appears when a player sits in the pilot or co-pilot seat of a plane or helicopter. Passengers in the back don&#39;t see it. It stays on when the engine is off; engine gauges simply drop to zero. The PFD never starts or stops the engine itself.</p><p>When you get in, the avionics boot first. F10 stays locked until the display shows READY.</p><h3 id="clicking-the-pfd-needs-the-f10-cursor" tabindex="-1">Clicking the PFD needs the F10 cursor <a class="header-anchor" href="#clicking-the-pfd-needs-the-f10-cursor" aria-label="Permalink to &quot;Clicking the PFD needs the F10 cursor&quot;">​</a></h3><p>Every button and knob on the PFD is clicked with the mouse, and the mouse only reaches the PFD while the <strong>F10</strong> cursor is open. Press F10 again to close it. If F10 is taken on your server, <code>/atccursor</code> does the same. Your keyboard keeps driving the game while the cursor is open.</p><h3 id="what-s-on-it" tabindex="-1">What&#39;s on it <a class="header-anchor" href="#what-s-on-it" aria-label="Permalink to &quot;What&#39;s on it&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>Shows</th></tr></thead><tbody><tr><td>Attitude indicator</td><td>Pitch ladder, bank, flight path marker, a small TAWS terrain grid in the corner. Red chevrons appear in an extreme nose-up or nose-down attitude and point back to the horizon</td></tr><tr><td>Speed and altitude</td><td>Airspeed in knots, altitude in feet</td></tr><tr><td>Data strip</td><td>Gear, ground speed, throttle, body health, engine health, lights. Each cell can be hidden by the owner</td></tr><tr><td>Left panel</td><td>Flight data</td></tr><tr><td>Right panel</td><td>Engine and fuel</td></tr><tr><td>Map</td><td>Moving map with runways, airports and nearby traffic (5 km range by default)</td></tr><tr><td>Wind</td><td>Wind direction and speed, plus the headwind and crosswind part</td></tr></tbody></table><h3 id="bezel-buttons" tabindex="-1">Bezel buttons <a class="header-anchor" href="#bezel-buttons" aria-label="Permalink to &quot;Bezel buttons&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Does</th></tr></thead><tbody><tr><td>REQ LAND · REQ TKOF</td><td>Pick a runway and request landing or take-off</td></tr><tr><td>CLR RWY</td><td>Release your runway</td></tr><tr><td>MAP</td><td>Open the large map</td></tr><tr><td>LTS · BODY · ENG · FUEL</td><td>Lights, damage, engine and fuel pages</td></tr><tr><td>CFG</td><td>Layout, scale, volume and display options</td></tr><tr><td>ALRT</td><td>Expand the warnings list</td></tr><tr><td>SOS</td><td>Emergency (squawk 7700)</td></tr><tr><td>GEAR</td><td>Raise or lower the gear</td></tr><tr><td>AP · AL · HV</td><td>Autopilot, autoland, auto-hover</td></tr><tr><td>ADV</td><td>Switch between the full PFD and a small simple HUD</td></tr></tbody></table><h3 id="warnings-and-callouts" tabindex="-1">Warnings and callouts <a class="header-anchor" href="#warnings-and-callouts" aria-label="Permalink to &quot;Warnings and callouts&quot;">​</a></h3><p>Spoken callouts warn about:</p><ul><li><strong>Terrain (TAWS/GPWS)</strong>: &quot;Caution Terrain&quot;, &quot;Terrain, Terrain&quot; and &quot;Pull Up&quot; when you descend fast close to the ground. Planes get the first warning at 500 ft above ground, helicopters at 150 ft.</li><li><strong>Stall</strong> and <strong>overspeed</strong>.</li><li><strong>Sink rate</strong>, <strong>bank angle</strong> (from 40°), <strong>don&#39;t sink</strong> after take-off, and <strong>too low, gear</strong> on approach with the gear up.</li><li><strong>Windshear</strong> on take-off and approach.</li><li><strong>V1</strong> on the take-off roll and <strong>minimums</strong> at 200 ft above ground on approach.</li></ul><p>Players set the callout volume with the <strong>Callout sounds</strong> slider in CFG. At 0 every warning sound is silent.</p><h2 id="moving-and-resizing-the-pfd" tabindex="-1">Moving and resizing the PFD <a class="header-anchor" href="#moving-and-resizing-the-pfd" aria-label="Permalink to &quot;Moving and resizing the PFD&quot;">​</a></h2><ol><li>Open the F10 cursor.</li><li>Click <strong>CFG</strong> on the bezel.</li><li>Drag the <strong>DRAG TO MOVE</strong> bar to move the PFD.</li><li>Pick a <strong>PFD scale</strong>: 50%, 75%, 100% or 125%. The ATC transcript has its own scale.</li><li>Use the switches to hide the PFD or the ATC transcript, or to turn the TAWS terrain grid and the runway guide on or off.</li><li>Click <strong>DONE</strong>.</li></ol><p>The layout is saved on the player&#39;s own PC and comes back next time. The PFD is always pulled back on screen after a resolution change.</p><p>If a panel ends up off screen, too small or hidden, type <code>/resetpilothud</code>. It restores the position, scale, hidden panels and floating map to their defaults.</p><h2 id="owner-defaults-hud-config-overrides-js" tabindex="-1">Owner defaults: hud-config-overrides.js <a class="header-anchor" href="#owner-defaults-hud-config-overrides-js" aria-label="Permalink to &quot;Owner defaults: hud-config-overrides.js&quot;">​</a></h2><p>Owners set HUD defaults for everyone in <code>html/hud-config-overrides.js</code>. Updates never replace this file.</p><ol><li><p>Rename <code>html/hud-config-overrides.js.example</code> to <code>html/hud-config-overrides.js</code>.</p></li><li><p>Set single fields, one per line:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.HUDConfig.atc.volume        </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ATC voice volume</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.HUDConfig.minimumsAlt       </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &quot;Minimums&quot; callout height, 0 = off</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.HUDConfig.panels.engPanel   </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// hide the right engine/fuel panel</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.HUDConfig.dataStrip.lights  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// hide one data-strip cell</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.HUDConfig.nd.range          </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// map range in metres</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.HUDConfig.sounds.gear_up    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sounds/my-gearup.mp3&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p>Restart the resource.</p></li></ol><p>Never replace a whole block (for example <code>window.HUDConfig.atc = { ... }</code>), or you lose every other key in it. Position and scale are each player&#39;s own choice and aren&#39;t set here.</p><h2 id="autopilot" tabindex="-1">Autopilot <a class="header-anchor" href="#autopilot" aria-label="Permalink to &quot;Autopilot&quot;">​</a></h2><p>Planes only. The autopilot flies the aircraft through GTA&#39;s own flight model, so it banks and climbs like a real aircraft.</p><h3 id="before-you-engage" tabindex="-1">Before you engage <a class="header-anchor" href="#before-you-engage" aria-label="Permalink to &quot;Before you engage&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Default</th></tr></thead><tbody><tr><td>You are the pilot of a plane (not a helicopter)</td><td></td></tr><tr><td>Height above ground</td><td>At least 400 ft</td></tr><tr><td>Aircraft health</td><td>Above 65%</td></tr><tr><td>Somewhere to go</td><td>A map waypoint, a flight plan filed in the tablet, or a heading set on the heading bug</td></tr></tbody></table><p>The gear retracts on its own when you engage. The engine is switched on if it was off.</p><h3 id="engage-and-disengage" tabindex="-1">Engage and disengage <a class="header-anchor" href="#engage-and-disengage" aria-label="Permalink to &quot;Engage and disengage&quot;">​</a></h3><ul><li>Click <strong>AP</strong> on the PFD, or type <code>/autopilot</code>.</li><li><code>/autopilot</code> has no key by default. Bind one in <strong>Settings → Key Bindings → FiveM</strong> under &quot;Toggle autopilot (AP)&quot;.</li><li>It disengages when you move the controls, lower the gear, or the aircraft gets too damaged.</li></ul><h3 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Steers by</th></tr></thead><tbody><tr><td><strong>NAV</strong></td><td>Your map waypoint or your filed flight plan (up to 10 waypoints)</td></tr><tr><td><strong>HDG</strong></td><td>The heading bug</td></tr></tbody></table><p>Turning the heading bug switches to HDG. Click the mode chip on the PFD, or use <code>/apmode</code>, to switch back.</p><h3 id="heading-and-altitude-selectors" tabindex="-1">Heading and altitude selectors <a class="header-anchor" href="#heading-and-altitude-selectors" aria-label="Permalink to &quot;Heading and altitude selectors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Scroll</th><th>Shift + scroll</th><th>Click</th></tr></thead><tbody><tr><td>HDG knob or box</td><td>1°</td><td>10°</td><td>Type an exact heading</td></tr><tr><td>ALT knob or ALT SEL box</td><td>100 ft</td><td>1,000 ft</td><td>Type an exact altitude</td></tr></tbody></table><p>The altitude selector goes up to <strong>8,500 ft</strong>. Altitudes from a filed flight plan are held to the same cap. Descents follow a 3° path. A dialled altitude takes effect at once if the autopilot is already flying.</p><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><p>Commands work without the F10 cursor.</p><table tabindex="0"><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>/autopilot</code></td><td>Engage or disengage</td></tr><tr><td><code>/apheading &lt;0-359&gt;</code></td><td>Set the heading bug. Leave the number out to type it in a box</td></tr><tr><td><code>/apalt &lt;feet&gt;</code></td><td>Set the altitude bug in feet above sea level. Leave the number out to type it in a box</td></tr><tr><td><code>/apmode nav</code> · <code>/apmode hdg</code></td><td>Pick a mode. Without a word it toggles</td></tr></tbody></table><h2 id="autoland" tabindex="-1">Autoland <a class="header-anchor" href="#autoland" aria-label="Permalink to &quot;Autoland&quot;">​</a></h2><p>Planes only. Autoland flies the approach and lands on a runway you reserved.</p><ol><li>Reserve a landing runway: <strong>REQ LAND</strong> on the PFD, or the F10 ATC menu. A controller approves it if one is on duty; otherwise you reserve it yourself.</li><li>Fly to within about 4 km of the airport, roughly lined up with the runway.</li><li>Click <strong>AL</strong> on the PFD, or type <code>/autolanding</code>.</li></ol><p>Without a landing reservation autoland refuses. The gear comes down by itself. If you arrive too high, the aircraft flies a descending circle near the airport to lose height, then lines up and lands. Press <strong>AL</strong> or <code>/autolanding</code> again to cancel.</p><p><code>/autolanding</code> has no key by default. Bind one in <strong>Settings → Key Bindings → FiveM</strong> under &quot;Toggle auto-landing (AL)&quot;.</p><h2 id="auto-hover-helicopters" tabindex="-1">Auto-hover (helicopters) <a class="header-anchor" href="#auto-hover-helicopters" aria-label="Permalink to &quot;Auto-hover (helicopters)&quot;">​</a></h2><p>Click <strong>HV</strong> on the PFD to hold a steady hover. The helicopter keeps its height and comes to a near stop, with a little wind drift.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Default</th></tr></thead><tbody><tr><td>Engine</td><td>Running</td></tr><tr><td>Height above ground</td><td>Above 8 ft</td></tr><tr><td>Health</td><td>Above 50%</td></tr><tr><td>Autopilot</td><td>Off</td></tr></tbody></table><p>Moving the controls takes over again. Auto-hover has no command or key binding; it&#39;s the HV button only.</p><h2 id="throttle" tabindex="-1">Throttle <a class="header-anchor" href="#throttle" aria-label="Permalink to &quot;Throttle&quot;">​</a></h2><p>Aircraft use GTA&#39;s normal throttle controls. There is no separate throttle lever.</p><h2 id="tcas" tabindex="-1">TCAS <a class="header-anchor" href="#tcas" aria-label="Permalink to &quot;TCAS&quot;">​</a></h2><p>TCAS warns about other aircraft close to you.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td>Scan range, plane in the air</td><td>2,500 m</td></tr><tr><td>Scan range, plane on the ground</td><td>400 m</td></tr><tr><td>Scan range, helicopter</td><td>1,500 m in the air, 300 m on the ground</td></tr><tr><td>&quot;Traffic, Traffic&quot;</td><td>Converging traffic within 1,800 m and 250 ft vertically</td></tr><tr><td>&quot;Climb&quot; / &quot;Descend&quot;</td><td>Converging traffic within 900 m</td></tr></tbody></table><p>Near the ground TCAS goes quieter: no &quot;Descend&quot; below 500 ft, only traffic alerts below 300 ft, and nothing below 75 ft. TCAS runs a self-test when the avionics boot; a badly damaged aircraft can fail it.</p><h2 id="wind" tabindex="-1">Wind <a class="header-anchor" href="#wind" aria-label="Permalink to &quot;Wind&quot;">​</a></h2><p>Everyone on the server feels the same wind.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td>Steady wind</td><td>3 to 18 knots</td></tr><tr><td>Direction and speed change</td><td>Every 5 minutes, drifting smoothly</td></tr><tr><td>Gusts</td><td>On top of the steady wind, near airports only (within 3 km, on approach or departure with the gear down)</td></tr><tr><td>Weather</td><td>Rain, thunder and blizzards make it stronger and gustier; fog and smog calmer. Capped at 35 knots steady and 40 knots of gusts</td></tr></tbody></table><p>Wind pushes the aircraft sideways and never speeds it up or slows it down. It also acts on the take-off and landing roll. A sudden gust near an airport triggers the &quot;Windshear&quot; callout. Autoland ignores wind unless the owner sets <code>Config.Weather.autolandWind = true</code>, which makes it crab into the crosswind and refuse to land above 25 knots of crosswind or 10 knots of tailwind.</p><p>Turn wind off with <code>Config.Features.wind = false</code>.</p><h2 id="malfunctions" tabindex="-1">Malfunctions <a class="header-anchor" href="#malfunctions" aria-label="Permalink to &quot;Malfunctions&quot;">​</a></h2><p>Malfunctions can happen while flying.</p><table tabindex="0"><thead><tr><th>Type</th><th>Chance weight</th></tr></thead><tbody><tr><td>Stuck landing gear</td><td>25</td></tr><tr><td>Fuel leak</td><td>25</td></tr><tr><td>Engine failure</td><td>20</td></tr><tr><td>Electrical failure</td><td>15</td></tr><tr><td>Hydraulic failure (heavy steering)</td><td>15</td></tr></tbody></table><ul><li><strong>During a job</strong>, the base chance is 3% every 30 seconds. A well-kept aircraft (maintenance and engine health both 80% or more) gets a tenth of that. Maintenance of 50% or more gets 40%. Below that the chance climbs, and a damaged engine raises it further.</li><li><strong>Outside a job</strong>, players on the pilot job (everyone in open-access mode) get 40% of the base chance, and owned aircraft at or below 30% maintenance get more.</li><li>During a malfunction, altitude zones don&#39;t apply and an off-runway landing isn&#39;t penalised, so you can put the aircraft down anywhere.</li></ul><p>Turn them off with <code>Config.Malfunctions.enabled = false</code>.</p><h2 id="fuel-repairs-and-insurance" tabindex="-1">Fuel, repairs and insurance <a class="header-anchor" href="#fuel-repairs-and-insurance" aria-label="Permalink to &quot;Fuel, repairs and insurance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Default</th></tr></thead><tbody><tr><td>Fuel price</td><td>$8 per gallon</td></tr><tr><td>Fuel display</td><td>Litres on the gauge, fuel page and refuel dialog (<code>Config.Economy.fuelDisplayUnit = &#39;percent&#39;</code> shows a percentage)</td></tr><tr><td>Maintenance wear</td><td>2% per flight hour, plus 10% per hard landing</td></tr><tr><td>Low maintenance</td><td>Below 30%, the engine stutters at random</td></tr><tr><td>Repair</td><td>$10 per point</td></tr><tr><td>Insurance</td><td>1% of the purchase price, lasts 30 days</td></tr></tbody></table><p>Refuel and repair at the aircraft mechanic. Insurance is bought and claimed at the mechanic or the dealer.</p><ul><li>A <strong>claim</strong> brings a destroyed aircraft back with full health and fuel, and ends the policy.</li><li>A destroyed aircraft <strong>without insurance</strong> comes back after a server restart at 40% health with an empty tank. Repair and refuel it before flying a job.</li></ul><p>Prices are set in <code>Config.Prices</code>. See <a href="./economy">Economy and pay</a>.</p>`,69)])])}const g=e(o,[["render",r]]);export{u as __pageData,g as default};
